    /** Whether an invoice needs approval before it is sent, has been approved, or needs none. */
    public enum Approval {
        NOT_NEEDED, NEEDS_APPROVAL, APPROVED
    }

    /**
     * The grand total above which a draft needs approval: the approval limit (the client tier's, else the workspace's) in US dollars
     * converted at the issue date's rate, rounded down to the step; null when none is set. A MEDIUM payment risk
     * client's limit is halved in US dollars before it is converted.
     */
    private BigDecimal approvalLimit() {
        if (approvalLimitUsd == null) {
            return null;
        }
        BigDecimal usd = new BigDecimal(approvalLimitUsd.trim());
        if (approvalLimitHalved) {
            usd = usd.divide(BigDecimal.valueOf(2));
        }
        return currency().divideDownToStep(usd, usdPerOn(issueDate));
    }

    /** Halves the approval limit (or restores it): a MEDIUM payment risk client has half the limit. */
    public void halveApprovalLimit(boolean halved) {
        this.approvalLimitHalved = halved;
    }

    /**
     * The total a draft is judged and approved on at the tax rate: the plan total (with its interest and plan fee)
     * when it has an instalment plan, else the grand total.
     */
    public BigDecimal approvalTotal(BigDecimal taxRate) {
        return hasPlan() ? planTotal(taxRate) : total(taxRate);
    }

    /** The number of days an approval stays good after the day it was given: as many as the client's tier allows. */
    public int approvalDays() {
        ClientTier tier = ClientTier.orStandard(clientTier);
        return (tier == null ? ClientTier.STANDARD : tier).approvalDays();
    }

    /**
     * The invoice's approval at the tax rate as of today, judged on its {@link #approvalTotal}: a credit note, or an invoice whose grand total
     * (before any withholding) is not over the approval limit and whose discount takes off no more than a
     * fifth of the subtotal, needs none; otherwise it is approved while its grand total is exactly the total
     * it was approved at and no more than {@link #approvalDays} days have passed since it was approved.
     * Once sent, an invoice is as it was approved. Every draft of a client with a HIGH payment risk (highRisk)
     * needs approval, whatever its size, as does every draft that would take its client over its credit limit
     * (overCreditLimit). A draft whose grand total is more than twice the approval limit needs
     * {@link #approvalsRequired two approvals} of that same total.
     */
    public Approval approval(BigDecimal taxRate, LocalDate today, boolean highRisk, boolean overCreditLimit) {
        if (isCreditNote()) {
            return Approval.NOT_NEEDED;
        }
        if (!isDraft()) {
            return approvedTotal == null ? Approval.NOT_NEEDED : Approval.APPROVED;
        }
        BigDecimal limit = approvalLimit();
        BigDecimal total = approvalTotal(taxRate);
        if (!highRisk && !overCreditLimit && !discountIsLarge() && (limit == null || total.compareTo(limit) <= 0)) {
            return Approval.NOT_NEEDED;
        }
        return approvalsAt(total, today) < approvalsRequired(taxRate) ? Approval.NEEDS_APPROVAL : Approval.APPROVED;
    }

    /** The approvals a draft needs: two when its grand total is more than twice the approval limit, else one. */
    public int approvalsRequired(BigDecimal taxRate) {
        BigDecimal limit = approvalLimit();
        return limit != null && approvalTotal(taxRate).compareTo(limit.multiply(BigDecimal.valueOf(2))) > 0 ? 2 : 1;
    }

    /**
     * The approvals that still stand for the grand total as of today: those given at exactly that total,
     * unless more than {@link #approvalDays} days have passed since the last of them; else none.
     */
    private int approvalsAt(BigDecimal total, LocalDate today) {
        if (approvedTotal == null || total.compareTo(approvedTotal) != 0) {
            return 0;
        }
        boolean lapsed = approvedOn != null && today.isAfter(approvedOn.plusDays(approvalDays()));
        return lapsed ? 0 : approvals;
    }

    /** The approvals the invoice still needs before it is sent, given its approval: none unless it needs approval. */
    public int approvalsNeeded(Approval approval, BigDecimal taxRate, LocalDate today) {
        if (approval != Approval.NEEDS_APPROVAL) {
            return 0;
        }
        return Math.max(1, approvalsRequired(taxRate) - approvalsAt(approvalTotal(taxRate), today));
    }

    /** The approvals that stand for the grand total as of today (see {@link #approvalsNeeded}). */
    public int approvalsGiven(BigDecimal taxRate, LocalDate today) {
        return approvalsAt(approvalTotal(taxRate), today);
    }

    public int getApprovals() {
        return approvals;
    }

    public BigDecimal getApprovedTotal() {
        return approvedTotal;
    }

    public LocalDate getApprovedOn() {
        return approvedOn;
    }

    /**
     * Approves the invoice at the grand total on the day: one more approval when the approvals given still
     * stand for that total, else its first.
     */
    public void approve(BigDecimal total, LocalDate on) {
        this.approvals = approvalsAt(total, on) + 1;
        this.approvedTotal = total;
        this.approvedOn = on;
    }

